SELECT gen_random_uuid()::text, 'formula', '$F_x$', 'Rectangular Components of a Force', '$F_x = F\cos\theta_x,\quad F_y = F\cos\theta_y,\quad F_z = F\cos\theta_z;\qquad \cos^2\theta_x + \cos^2\theta_y + \cos^2\theta_z = 1$', '$\text{N}$', 'A force split along the axes by its direction cosines.', '[{"symbol":"$F$","meaning":"force","unit":"$\\text{N}$"},{"symbol":"$\\theta_x, \\theta_y, \\theta_z$","meaning":"angles the force makes with the axes","unit":null}]'::jsonb, 'Along a line from A to B: $\vec F = F\frac{\overrightarrow{AB}}{|AB|}$.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'force systems and resultants' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
