SELECT gen_random_uuid()::text, 'formula', '$\frac{F_1}{\sin\alpha}$', 'Lami''s Theorem', '$\frac{F_1}{\sin\alpha} = \frac{F_2}{\sin\beta} = \frac{F_3}{\sin\gamma}$', '$\text{N}$', 'Three concurrent forces in balance: each is proportional to the sine of the angle between the other two.', '[{"symbol":"$F_1, F_2, F_3$","meaning":"three concurrent forces in equilibrium","unit":"$\\text{N}$"},{"symbol":"$\\alpha, \\beta, \\gamma$","meaning":"the angle between the OTHER two forces","unit":null}]'::jsonb, 'Each angle is opposite its force. Three forces in equilibrium are concurrent or parallel.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'equilibrium' AND s."active"), NULL, false, 'PENDING', now(), now()
