SELECT gen_random_uuid()::text, 'formula', '$R_A$', 'Reactions of a Simply Supported Beam', '$R_A = \frac{Pb}{L},\qquad R_B = \frac{Pa}{L}$', '$\text{N}$', 'Support reactions for a point load on a beam on two supports.', '[{"symbol":"$P$","meaning":"point load","unit":"$\\text{N}$"},{"symbol":"$a, b$","meaning":"distances from the load to supports A and B","unit":"$\\text{m}$"},{"symbol":"$L$","meaning":"span, a + b","unit":"$\\text{m}$"}]'::jsonb, 'The support NEARER the load carries more.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'equilibrium' AND s."active"), NULL, false, 'PENDING', now(), now()
