SELECT gen_random_uuid()::text, 'formula', '$m + r = 2j$', 'Truss Stability and Determinacy', '$m + r = 2j\ \text{(determinate)};\quad m + r < 2j\ \text{(unstable)};\quad m + r > 2j\ \text{(indeterminate)}$', NULL, 'Whether a plane truss can be solved by statics alone.', '[{"symbol":"$m$","meaning":"members","unit":null},{"symbol":"$r$","meaning":"support reactions","unit":null},{"symbol":"$j$","meaning":"joints","unit":null}]'::jsonb, 'Meeting the count is necessary, not sufficient: the members must also be arranged rigidly.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'trusses' AND s."active"), NULL, true, 'PENDING', now(), now()
