SELECT gen_random_uuid()::text, 'formula', '$H$', 'Parabolic Cable', '$H = \frac{wL^2}{8d},\qquad T_{\max} = \sqrt{H^2 + \left(\tfrac{wL}{2}\right)^2},\qquad s \approx L + \frac{8d^2}{3L}$', '$\text{N}$', 'A cable carrying a load uniform along the horizontal (a suspension bridge) hangs as a parabola.', '[{"symbol":"$w$","meaning":"load per HORIZONTAL metre","unit":"$\\text{N/m}$"},{"symbol":"$L$","meaning":"span","unit":"$\\text{m}$"},{"symbol":"$d$","meaning":"sag at mid-span","unit":"$\\text{m}$"}]'::jsonb, 'H is the same everywhere; the tension is greatest at the supports.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'cables' AND s."active"), NULL, false, 'PENDING', now(), now()
