SELECT gen_random_uuid()::text, 'formula', '$y = c\cosh\frac xc$', 'Catenary', '$y = c\cosh\frac{x}{c},\quad s = c\sinh\frac{x}{c},\quad y^2 = s^2 + c^2,\quad H = wc,\quad T = wy$', '$\text{m}$', 'A cable hanging under its own weight.', '[{"symbol":"$w$","meaning":"weight per metre ALONG the cable","unit":"$\\text{N/m}$"},{"symbol":"$c$","meaning":"parameter, H/w","unit":"$\\text{m}$"},{"symbol":"$s$","meaning":"length from the lowest point","unit":"$\\text{m}$"}]'::jsonb, 'The tension at any point equals w times its height above the directrix (y measured from c below the lowest point).', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'cables' AND s."active"), NULL, false, 'PENDING', now(), now()
