SELECT gen_random_uuid()::text, 'formula', '$M$', 'Square-Threaded Screw', '$M = Wr\tan(\phi + \alpha)\ \text{(raising)},\qquad \tan\alpha = \frac{L}{2\pi r}$', '$\text{N}\cdot\text{m}$', 'The torque to raise a load with a screw jack.', '[{"symbol":"$W$","meaning":"weight","unit":"$\\text{N}$"},{"symbol":"$r$","meaning":"mean radius of the thread","unit":"$\\text{m}$"},{"symbol":"$\\phi$","meaning":"angle of friction","unit":null},{"symbol":"$\\alpha$","meaning":"lead angle","unit":null},{"symbol":"$L$","meaning":"lead","unit":"$\\text{m}$"}]'::jsonb, 'Lowering takes $Wr\tan(\phi - \alpha)$; the screw holds itself when $\phi > \alpha$.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'friction' AND s."active"), NULL, false, 'PENDING', now(), now()
