SELECT gen_random_uuid()::text, 'formula', '$\bar{x}$', 'Centroid of a Composite Area', '$\bar{x} = \frac{\sum A_i\bar{x}_i}{\sum A_i},\qquad \bar{y} = \frac{\sum A_i\bar{y}_i}{\sum A_i}$', '$\text{m}$', 'The centroid of a shape built from simple ones.', '[{"symbol":"$A_i$","meaning":"area of each part (holes negative)","unit":"$\\text{m}^2$"},{"symbol":"$\\bar{x}_i, \\bar{y}_i$","meaning":"centroid of each part","unit":"$\\text{m}$"}]'::jsonb, 'A hole counts as a negative area.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'centroids' AND s."active"), NULL, false, 'PENDING', now(), now()
