SELECT gen_random_uuid()::text, 'formula', '$\bar{y}$', 'Centroids of Common Shapes', '$\text{triangle } \tfrac h3 \text{ (from base)};\ \text{semicircle } \tfrac{4r}{3\pi};\ \text{quarter circle } \tfrac{4r}{3\pi}, \tfrac{4r}{3\pi};\ \text{sector } \tfrac{2r\sin\alpha}{3\alpha};\ \text{arc } \tfrac{r\sin\alpha}{\alpha}$', '$\text{m}$', 'Where the centroids of the shapes in a composite sit.', '[{"symbol":"$r$","meaning":"radius","unit":"$\\text{m}$"},{"symbol":"$\\alpha$","meaning":"half-angle in radians","unit":null},{"symbol":"$h$","meaning":"height","unit":"$\\text{m}$"}]'::jsonb, 'For the sector and arc, measure from the centre along the axis of symmetry. A semicircle''s is $0.424r$.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'centroids' AND s."active"), NULL, false, 'PENDING', now(), now()
