SELECT gen_random_uuid()::text, 'formula', '$V = 2\pi\bar{y}A$', 'Theorems of Pappus', '$A_s = 2\pi\bar{y}L,\qquad V = 2\pi\bar{y}A$', '$\text{m}^3$', 'Surface area and volume of a solid of revolution from the path of the centroid.', '[{"symbol":"$\\bar{y}$","meaning":"distance of the centroid from the axis","unit":"$\\text{m}$"},{"symbol":"$L$","meaning":"length of the curve","unit":"$\\text{m}$"},{"symbol":"$A$","meaning":"area","unit":"$\\text{m}^2$"}]'::jsonb, 'A torus: $V = 2\pi R(\pi r^2)$.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'centroids' AND s."active"), NULL, false, 'PENDING', now(), now()
