SELECT gen_random_uuid()::text, 'formula', '$I$', 'Area Moments of Inertia of Common Shapes', '$\text{rectangle } \tfrac{bh^3}{12} (\text{centroid}), \tfrac{bh^3}{3} (\text{base});\ \text{triangle } \tfrac{bh^3}{36}, \tfrac{bh^3}{12};\ \text{circle } \tfrac{\pi r^4}{4}$', '$\text{m}^4$', 'Second moments of area about centroidal and base axes.', '[{"symbol":"$b, h$","meaning":"width and height","unit":"$\\text{m}$"},{"symbol":"$r$","meaning":"radius","unit":"$\\text{m}$"}]'::jsonb, 'h is measured square to the axis, and is the cubed dimension.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'moments of inertia' AND s."active"), NULL, false, 'PENDING', now(), now()
