SELECT gen_random_uuid()::text, 'formula', '$I = \bar{I} + Ad^2$', 'Parallel-Axis Theorem for Areas', '$I = \bar{I} + Ad^2$', '$\text{m}^4$', 'Moment of inertia about any axis parallel to a centroidal one.', '[{"symbol":"$\\bar{I}$","meaning":"about the centroidal axis","unit":"$\\text{m}^4$"},{"symbol":"$A$","meaning":"area","unit":"$\\text{m}^2$"},{"symbol":"$d$","meaning":"distance between the axes","unit":"$\\text{m}$"}]'::jsonb, 'Always transfer FROM the centroidal axis; transferring between two non-centroidal axes needs two steps.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'moments of inertia' AND s."active"), NULL, false, 'PENDING', now(), now()
