SELECT gen_random_uuid()::text, 'formula', '$J$', 'Polar Moment of Inertia', '$J = I_x + I_y;\qquad \text{solid circle } \tfrac{\pi r^4}{2} = \tfrac{\pi d^4}{32}$', '$\text{m}^4$', 'The second moment about an axis square to the area, through the same point.', '[{"symbol":"$I_x, I_y$","meaning":"moments about two perpendicular axes in the plane","unit":"$\\text{m}^4$"}]'::jsonb, 'A hollow shaft: $\frac{\pi(d_o^4 - d_i^4)}{32}$. Used for torsion.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'moments of inertia' AND s."active"), NULL, false, 'PENDING', now(), now()
