SELECT gen_random_uuid()::text, 'formula', '$a = v\frac{dv}{dx}$', 'Motion with Variable Acceleration', '$v = \frac{dx}{dt},\qquad a = \frac{dv}{dt} = v\frac{dv}{dx}$', '$\text{m/s}^2$', 'Position, velocity and acceleration linked by calculus when the acceleration varies.', '[{"symbol":"$x$","meaning":"position","unit":"$\\text{m}$"},{"symbol":"$v$","meaning":"velocity","unit":"$\\text{m/s}$"},{"symbol":"$a$","meaning":"acceleration","unit":"$\\text{m/s}^2$"}]'::jsonb, 'If $a$ depends on $x$, use $a = v\frac{dv}{dx}$ and integrate.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'rectilinear motion' AND s."active"), NULL, false, 'PENDING', now(), now()
