SELECT gen_random_uuid()::text, 'formula', '$d$', 'Stopping Distance', '$d = vt_r + \frac{v^2}{2a},\qquad \text{on a level road } a = \mu g$', '$\text{m}$', 'Distance to stop: travel during the reaction time, then braking.', '[{"symbol":"$v$","meaning":"initial speed","unit":"$\\text{m/s}$"},{"symbol":"$t_r$","meaning":"reaction time","unit":"$\\text{s}$"},{"symbol":"$a$","meaning":"braking deceleration","unit":"$\\text{m/s}^2$"}]'::jsonb, 'Doubling the speed quadruples the braking distance.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'rectilinear motion' AND s."active"), NULL, false, 'PENDING', now(), now()
