SELECT gen_random_uuid()::text, 'formula', '$y(x)$', 'Trajectory of a Projectile', '$y = x\tan\theta - \frac{gx^2}{2v_0^2\cos^2\theta}$', '$\text{m}$', 'The parabola a projectile follows.', '[{"symbol":"$v_0$","meaning":"launch speed","unit":"$\\text{m/s}$"},{"symbol":"$\\theta$","meaning":"launch angle","unit":null},{"symbol":"$g$","meaning":"acceleration due to gravity","unit":"$\\text{m/s}^2$"}]'::jsonb, 'To clear a wall at (x, y), put it in and solve for v₀ or θ.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'projectile motion' AND s."active"), NULL, false, 'PENDING', now(), now()
