SELECT gen_random_uuid()::text, 'formula', '$t$', 'Projectile Launched from a Height', '$y_0 + v_0\sin\theta\,t - \tfrac12gt^2 = 0,\qquad x = v_0\cos\theta\,t$', '$\text{s}$', 'Time and distance when launch and landing heights differ: solve the quadratic for t.', '[{"symbol":"$y_0$","meaning":"launch height above the landing level","unit":"$\\text{m}$"},{"symbol":"$v_0$","meaning":"launch speed","unit":"$\\text{m/s}$"},{"symbol":"$\\theta$","meaning":"launch angle","unit":null}]'::jsonb, 'Take the positive root. Horizontal launch: θ = 0, t = √(2y₀/g).', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'projectile motion' AND s."active"), NULL, false, 'PENDING', now(), now()
