SELECT gen_random_uuid()::text, 'formula', '$\theta,\ 90^\circ - \theta$', 'Complementary Angles for the Same Range', '$R(\theta) = R(90^\circ - \theta)$', NULL, 'Two launch angles that add to 90° land at the same distance (from level ground).', '[{"symbol":"$\\theta$","meaning":"launch angle","unit":null}]'::jsonb, 'The higher one stays up longer.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'projectile motion' AND s."active"), NULL, true, 'PENDING', now(), now()
