SELECT gen_random_uuid()::text, 'formula', '$a$', 'Tangential and Normal Acceleration', '$a_t = \frac{dv}{dt},\qquad a_n = \frac{v^2}{\rho},\qquad a = \sqrt{a_t^2 + a_n^2}$', '$\text{m/s}^2$', 'A body on a curved path speeding up has both components of acceleration.', '[{"symbol":"$v$","meaning":"speed","unit":"$\\text{m/s}$"},{"symbol":"$\\rho$","meaning":"radius of curvature","unit":"$\\text{m}$"}]'::jsonb, 'For $y = f(x)$: $\rho = \frac{[1 + (y'')^2]^{3/2}}{|y''''|}$.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'curvilinear motion' AND s."active"), NULL, false, 'PENDING', now(), now()
