SELECT gen_random_uuid()::text, 'formula', '$v_{\max}$', 'Maximum Speed on a Flat Curve', '$v_{\max} = \sqrt{\mu gr}$', '$\text{m/s}$', 'Friction alone supplies the centripetal force on an unbanked curve.', '[{"symbol":"$\\mu$","meaning":"coefficient of friction","unit":null},{"symbol":"$g$","meaning":"acceleration due to gravity","unit":"$\\text{m/s}^2$"},{"symbol":"$r$","meaning":"radius of the curve","unit":"$\\text{m}$"}]'::jsonb, 'Mass cancels: a truck and a car skid at the same speed.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'curvilinear motion' AND s."active"), NULL, false, 'PENDING', now(), now()
