SELECT gen_random_uuid()::text, 'formula', '$\tan\theta$', 'Banking of Curves', '$\tan\theta = \frac{v^2}{gr}\ \text{(no friction)};\qquad v_{\max} = \sqrt{gr\,\frac{\sin\theta + \mu\cos\theta}{\cos\theta - \mu\sin\theta}}$', '$\text{m/s}$', 'The bank angle that needs no friction at a design speed, and the top speed with friction.', '[{"symbol":"$\\theta$","meaning":"bank angle","unit":null},{"symbol":"$v$","meaning":"speed","unit":"$\\text{m/s}$"},{"symbol":"$r$","meaning":"radius","unit":"$\\text{m}$"},{"symbol":"$\\mu$","meaning":"coefficient of friction","unit":null}]'::jsonb, 'With friction, $v_{\max} = \sqrt{gr\tan(\theta + \phi)}$ where $\tan\phi = \mu$.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'curvilinear motion' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
