SELECT gen_random_uuid()::text, 'formula', '$T$', 'Conical Pendulum', '$\tan\theta = \frac{v^2}{rg},\qquad T = 2\pi\sqrt{\frac{L\cos\theta}{g}}$', '$\text{s}$', 'A mass whirled in a horizontal circle on a string.', '[{"symbol":"$L$","meaning":"string length","unit":"$\\text{m}$"},{"symbol":"$\\theta$","meaning":"angle of the string from vertical","unit":null},{"symbol":"$r$","meaning":"radius of the circle, L sin θ","unit":"$\\text{m}$"}]'::jsonb, 'The string tension is $\frac{mg}{\cos\theta}$.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'curvilinear motion' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
