SELECT gen_random_uuid()::text, 'formula', '$v_{\min}$', 'Motion in a Vertical Circle', '$v_{\min,\text{top}} = \sqrt{gr};\qquad T_{\text{bottom}} = \frac{mv^2}{r} + mg$', '$\text{m/s}$', 'The least speed at the top to keep a string taut, and the tension at the bottom.', '[{"symbol":"$g$","meaning":"acceleration due to gravity","unit":"$\\text{m/s}^2$"},{"symbol":"$r$","meaning":"radius","unit":"$\\text{m}$"},{"symbol":"$m$","meaning":"mass","unit":"$\\text{kg}$"}]'::jsonb, 'Released from rest to just make the loop on a track, start $\frac{5r}{2}$ above the bottom.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'curvilinear motion' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS'
