SELECT gen_random_uuid()::text, 'formula', '$\sum F - ma = 0$', 'D''Alembert''s Principle', '$\sum F + (-ma) = 0$', '$\text{N}$', 'Add the reversed effective force −ma and solve a dynamics problem as if it were statics.', '[{"symbol":"$F$","meaning":"force","unit":"$\\text{N}$"},{"symbol":"$m$","meaning":"mass","unit":"$\\text{kg}$"},{"symbol":"$a$","meaning":"acceleration","unit":"$\\text{m/s}^2$"}]'::jsonb, 'Moments about any point then work as in equilibrium.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'newton''s laws' AND s."active"), NULL, false, 'PENDING', now(), now()
