SELECT gen_random_uuid()::text, 'formula', '$a$', 'Atwood Machine', '$a = \frac{(m_1 - m_2)g}{m_1 + m_2},\qquad T = \frac{2m_1m_2g}{m_1 + m_2}$', '$\text{m/s}^2$', 'Two masses over a light frictionless pulley.', '[{"symbol":"$m_1, m_2$","meaning":"the two hanging masses","unit":"$\\text{kg}$"},{"symbol":"$g$","meaning":"acceleration due to gravity","unit":"$\\text{m/s}^2$"}]'::jsonb, 'The tension lies between the two weights.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'newton''s laws' AND s."active"), NULL, false, 'PENDING', now(), now()
