SELECT gen_random_uuid()::text, 'formula', '$W = \int F\,dx$', 'Work of a Variable Force', '$W = \int_{x_1}^{x_2} F\,dx;\qquad \text{spring: } W = \tfrac12k(x_2^2 - x_1^2)$', '$\text{J}$', 'Work is the area under the force-displacement curve.', '[{"symbol":"$F$","meaning":"force","unit":"$\\text{N}$"},{"symbol":"$x$","meaning":"position","unit":"$\\text{m}$"},{"symbol":"$k$","meaning":"spring constant","unit":"$\\text{N/m}$"}]'::jsonb, 'Stretching from 0.1 to 0.2 m takes 3 times the work of 0 to 0.1 m.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'work and energy' AND s."active"), NULL, false, 'PENDING', now(), now()
