SELECT gen_random_uuid()::text, 'formula', '$\Delta E$', 'Flywheel Energy and Fluctuation of Speed', '$\Delta E = \tfrac12I(\omega_{\max}^2 - \omega_{\min}^2) = I\omega^2C_s,\qquad C_s = \frac{\omega_{\max} - \omega_{\min}}{\omega}$', '$\text{J}$', 'The energy a flywheel absorbs or releases as its speed swings, used to size it.', '[{"symbol":"$I$","meaning":"moment of inertia","unit":"$\\text{kg}\\cdot\\text{m}^2$"},{"symbol":"$\\omega$","meaning":"mean speed","unit":"$\\text{rad/s}$"},{"symbol":"$C_s$","meaning":"coefficient of fluctuation of speed","unit":null}]'::jsonb, 'ω here is the mean of the maximum and minimum speeds.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Mechanics' AND t."subject" = 'ESAS' AND s."normKey" = 'rotation' AND s."active"), NULL, false, 'PENDING', now(), now()
